def foto(s):
    k, v = s.split(':', 1)
    if k == 'flag': return {'flag': v}
    if k == 'px': return {'q': v, 'src': 'px'}
    q, must = v.split('|'); return {'q': q, 'src': 'cm', 'must': must}


def main():
    r = random.Random(150)
    vistas = set(); preg = []
    for p, tp, ok, mal, fok, fmal, tr in F:
        clave = (p, frozenset((ok, mal)))
        assert clave not in vistas, ('repetida', p, ok, mal); vistas.add(clave)
        c = r.randint(0, 1)
        o = [ok, mal] if c == 0 else [mal, ok]; of = [foto(fok), foto(fmal)] if c == 0 else [foto(fmal), foto(fok)]
        if any('flag' in x for x in of) and not all('flag' in x for x in of): raise SystemExit(f'mezcla bandera y foto: {p}')
        preg.append({'n': len(preg) + 1, 'p': p, 'o': o, 'c': c, 'tp': tp, 'tr': tr, 'o_fotos': of})
    ep = {
        '_nota': 'Primer episodio completo del formato rápido «¿A o B?» (9-nov-2026). Escrito con scripts/escribir_rapido001.py; se descartan las preguntas sin fotos y quedan 150.',
        'id': 'rapido001', 'formato': 'rapido', 'max_preguntas': 150, 'total_titulo': 150, 'minimo': 140,
        'niveles_cada': 5, 'etapas': [1, 7, 15, 23], 'suscripcion_en': 50,
        'titulo': '¿A o B?',
        'titulo_youtube': '¿A o B? 150 preguntas en 30 minutos 🔥 ¿Hasta qué nivel llegas? | ¿Quién Sabe Más?',
        'descripcion': '150 preguntas de «¿A o B?» y cada vez MÁS RÁPIDO 🔥 MAX y NOVA corren, vuelan, suben a una nave y se teletransportan. '
                       '¿Hasta qué nivel llegas sin fallar? Escribe tu número en los comentarios 👇',
        'tags': ['a o b', 'preguntas de cultura general', 'quiz', 'trivia', 'qué prefieres', 'test de cultura general'],
        'extra_tts': {'an_arranque': ['anunciador', '¡Ciento cincuenta preguntas! ¿Hasta qué nivel llegas? ¡Vamos!']},
        'preguntas': preg,
    }
    out = os.path.join(os.path.dirname(__file__), '..', 'contenido', 'rapido', 'rapido001.json')
    json.dump(ep, open(out, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(len(preg), 'preguntas · izquierda correcta:', sum(q['c'] == 0 for q in preg))


if __name__ == '__main__':
    main()
